-- DARKSCRUB: Products & listings deployment (2026-11-05)
-- Select the EXISTING DarkScrub application database in phpMyAdmin, then import this file as UTF-8.
-- Requires the existing scrubdata, auth_permissions, auth_roles and auth_role_permissions tables.
-- Creates six independent product-builder tables and imports 53 UNI categories, 1517 designs and 12 Graphics versions.
-- Existing categories and their modelcodes, prices and coverage are preserved.
-- No products, employee assignments or database connection settings are imported.
-- No CREATE DATABASE, USE, DROP TABLE or TRUNCATE statements are needed.
SET NAMES utf8mb4;
-- Independent product builder; no dependency on the legacy catalogue.
CREATE TABLE IF NOT EXISTS product_builder_uni_categories (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 brand VARCHAR(100) NOT NULL, category_name VARCHAR(150) NOT NULL, modelcode VARCHAR(5) NOT NULL,
 included_models TEXT NOT NULL, price_unlicensed DECIMAL(10,2) NULL, price_licensed DECIMAL(10,2) NULL,
 version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_pb_uni_name (brand, category_name), UNIQUE KEY uq_pb_uni_modelcode (modelcode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS product_builder_boxes (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(150) NOT NULL,
 length_cm DECIMAL(7,2) NOT NULL, width_cm DECIMAL(7,2) NOT NULL, height_cm DECIMAL(7,2) NOT NULL,
 weight_kg DECIMAL(9,3) NOT NULL DEFAULT 0.000,
 version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_pb_box_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS product_builder_products (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(80) NOT NULL, name VARCHAR(255) NOT NULL,
 bundle_type VARCHAR(5) NOT NULL, category_kind ENUM('specific','universal') NOT NULL,
 uni_category_id BIGINT UNSIGNED NULL, brand VARCHAR(100) NOT NULL, model VARCHAR(150) NOT NULL,
 year_range VARCHAR(50) NOT NULL DEFAULT '', modelcode VARCHAR(7) NOT NULL, notes TEXT NOT NULL,
 recommended_price DECIMAL(10,2) NULL,
 recommended_currency CHAR(3) NOT NULL DEFAULT 'EUR',
 web_price DECIMAL(10,2) NULL,
 web_currency CHAR(3) NOT NULL DEFAULT 'EUR',
 ebay_price DECIMAL(10,2) NULL,
 ebay_currency CHAR(3) NOT NULL DEFAULT 'EUR',
 amazon_price DECIMAL(10,2) NULL,
 amazon_currency CHAR(3) NOT NULL DEFAULT 'EUR',
 box_id BIGINT UNSIGNED NULL,
 weight_kg DECIMAL(9,3) NULL,
 img_status VARCHAR(4) NOT NULL DEFAULT 'none',
 img_path TEXT NULL,
 img_version INT UNSIGNED NOT NULL DEFAULT 1,
 request_key CHAR(32) NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 1, created_by INT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_pb_sku (sku), UNIQUE KEY uq_pb_request (request_key), KEY idx_pb_modelcode (modelcode),
 CONSTRAINT fk_pb_product_box FOREIGN KEY (box_id) REFERENCES product_builder_boxes(id) ON DELETE RESTRICT,
 CONSTRAINT fk_pb_uni FOREIGN KEY (uni_category_id) REFERENCES product_builder_uni_categories(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS product_builder_designs (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 component_type ENUM('G','S') NOT NULL, name VARCHAR(255) NOT NULL,
 seed_key CHAR(64) NULL, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_pb_design_name (component_type,name), UNIQUE KEY uq_pb_design_seed (seed_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS product_builder_graphics_versions (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(30) NOT NULL, sort_order INT UNSIGNED NOT NULL DEFAULT 0,
 seed_key VARCHAR(30) NULL, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_pb_graphics_version_name (name), UNIQUE KEY uq_pb_graphics_version_seed (seed_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS product_builder_components (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL,
 component_type CHAR(1) NOT NULL, label VARCHAR(255) NOT NULL, reference VARCHAR(100) NOT NULL DEFAULT '',
 color VARCHAR(100) NOT NULL DEFAULT '', design_id BIGINT UNSIGNED NULL, graphics_version_id BIGINT UNSIGNED NULL,
 quantity INT UNSIGNED NOT NULL DEFAULT 1, notes TEXT NOT NULL, options_json LONGTEXT NULL, sort_order INT UNSIGNED NOT NULL DEFAULT 0,
 CONSTRAINT fk_pb_component_graphics_version FOREIGN KEY (graphics_version_id) REFERENCES product_builder_graphics_versions(id) ON DELETE RESTRICT,
 CONSTRAINT fk_pb_component_design FOREIGN KEY (design_id) REFERENCES product_builder_designs(id) ON DELETE RESTRICT,
 CONSTRAINT fk_pb_component_product FOREIGN KEY (product_id) REFERENCES product_builder_products(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- Product builder update 002: editable SKU, plastic item color and expandable components.
-- Select the existing DarkScrub database in phpMyAdmin and import this file before uploading the updated PHP files.
-- Existing products, SKUs and component details are preserved. Safe to import more than once.
SET @pb_has_color = (SELECT COUNT(*) FROM information_schema.columns
 WHERE table_schema=DATABASE() AND table_name='product_builder_components' AND column_name='color');
SET @pb_color_sql = IF(@pb_has_color=0,
 'ALTER TABLE product_builder_components ADD COLUMN color VARCHAR(100) NOT NULL DEFAULT '''' AFTER reference',
 'DO 0');
PREPARE pb_color_migration FROM @pb_color_sql;
EXECUTE pb_color_migration;
DEALLOCATE PREPARE pb_color_migration;

-- Product builder update 003: store the per-component fields used by Custom Orders.
-- Import into the existing application database. Existing products, SKUs, colors and notes are preserved.
-- Safe to import repeatedly. Requires the base product builder installation (including update 002).
SET @pb_has_options = (SELECT COUNT(*) FROM information_schema.columns
 WHERE table_schema=DATABASE() AND table_name='product_builder_components' AND column_name='options_json');
SET @pb_options_sql = IF(@pb_has_options=0,
 'ALTER TABLE product_builder_components ADD COLUMN options_json LONGTEXT NULL AFTER notes',
 'DO 0');
PREPARE pb_options_migration FROM @pb_options_sql;
EXECUTE pb_options_migration;
DEALLOCATE PREPARE pb_options_migration;

-- Session-local staging data; disappears when the phpMyAdmin connection closes.
CREATE TEMPORARY TABLE IF NOT EXISTS pb_deploy_uni_seed (
 brand VARCHAR(100) NOT NULL,
 category_name VARCHAR(150) NOT NULL,
 modelcode VARCHAR(5) NOT NULL,
 included_models TEXT NOT NULL,
 price_unlicensed DECIMAL(10,2) NULL,
 price_licensed DECIMAL(10,2) NULL,
 PRIMARY KEY (brand,category_name),
 UNIQUE KEY uq_pb_deploy_modelcode (modelcode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE modelcode=VALUES(modelcode),included_models=VALUES(included_models),price_unlicensed=VALUES(price_unlicensed),price_licensed=VALUES(price_licensed);

START TRANSACTION;

-- Skip existing brand/category pairs and modelcodes already used by another UNI category or a specific model.
-- Missing categories are listed at the end, so a server-specific collision is never imported silently.
SELECT seed.brand,seed.category_name,seed.modelcode,seed.included_models,seed.price_unlicensed,seed.price_licensed
FROM pb_deploy_uni_seed seed
WHERE NOT EXISTS (
 SELECT 1 FROM product_builder_uni_categories existing
 WHERE (existing.brand=seed.brand AND existing.category_name=seed.category_name)
    OR existing.modelcode=seed.modelcode
)
AND NOT EXISTS (SELECT 1 FROM scrubdata models WHERE models.modelcode=seed.modelcode);
-- Registers an unassigned role only. No employee role assignments are changed.
VALUES ('products.view','Products','Zobraziť produkty a listingy','Samostatný modul tvorby produktov a UNI kategórií.','normal',600,1),
('products.manage','Products','Spravovať produkty a UNI kategórie','Tvorba a úprava produktov, import a správa UNI kategórií.','normal',610,1)
ON DUPLICATE KEY UPDATE label=VALUES(label),description=VALUES(description);
VALUES ('product_manager','Products manager','Správa samostatnej databázy produktov a UNI kategórií.',1,1,500)
ON DUPLICATE KEY UPDATE label=VALUES(label);
SELECT r.id,p.id FROM auth_roles r CROSS JOIN auth_permissions p
WHERE r.role_key='product_manager' AND p.permission_key IN ('products.view','products.manage');

COMMIT;

-- Verification: expected_seed_categories = 53, installed_seed_categories = 53, missing_seed_categories = 0.
SELECT COUNT(*) AS expected_seed_categories,
 COUNT(installed.id) AS installed_seed_categories,
 COUNT(*)-COUNT(installed.id) AS missing_seed_categories
FROM pb_deploy_uni_seed seed
LEFT JOIN product_builder_uni_categories installed
 ON installed.brand=seed.brand AND installed.category_name=seed.category_name;

-- Expected: no rows. If listed, create these categories in Manage UNI categories to generate a free modelcode.
SELECT seed.brand,seed.category_name,seed.modelcode AS conflicting_modelcode,
 'Modelcode already in use; add this category through Manage UNI categories.' AS required_action
FROM pb_deploy_uni_seed seed
LEFT JOIN product_builder_uni_categories installed
 ON installed.brand=seed.brand AND installed.category_name=seed.category_name
WHERE installed.id IS NULL;
-- Product builder update 004: Graphics and Seat Covers design library.
-- Import into the existing application database after update 003.
-- Adds the library and optional component links; existing listing names and SKUs are preserved.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS product_builder_designs (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 component_type ENUM('G','S') NOT NULL, name VARCHAR(255) NOT NULL,
 seed_key CHAR(64) NULL, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_pb_design_name (component_type,name), UNIQUE KEY uq_pb_design_seed (seed_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET @pb_has_design = (SELECT COUNT(*) FROM information_schema.columns
 WHERE table_schema=DATABASE() AND table_name='product_builder_components' AND column_name='design_id');
SET @pb_design_sql = IF(@pb_has_design=0,
 'ALTER TABLE product_builder_components ADD COLUMN design_id BIGINT UNSIGNED NULL AFTER color', 'DO 0');
PREPARE pb_design_migration FROM @pb_design_sql;
EXECUTE pb_design_migration;
DEALLOCATE PREPARE pb_design_migration;
SET @pb_has_design_fk = (SELECT COUNT(*) FROM information_schema.table_constraints
 WHERE constraint_schema=DATABASE() AND table_name='product_builder_components' AND constraint_name='fk_pb_component_design');
SET @pb_design_sql = IF(@pb_has_design_fk=0,
 'ALTER TABLE product_builder_components ADD CONSTRAINT fk_pb_component_design FOREIGN KEY (design_id) REFERENCES product_builder_designs(id) ON DELETE RESTRICT', 'DO 0');
PREPARE pb_design_migration FROM @pb_design_sql;
EXECUTE pb_design_migration;
DEALLOCATE PREPARE pb_design_migration;
-- Supplied Designz.csv seed: 453 Graphics + 1064 Seat Covers; 5 repeated Graphics names merged.
-- Stable source keys preserve renamed designs when this import is repeated.
CREATE TEMPORARY TABLE IF NOT EXISTS pb_deploy_design_seed (
 component_type CHAR(1) NOT NULL, name VARCHAR(255) NOT NULL, seed_key CHAR(64) NOT NULL PRIMARY KEY,
 UNIQUE KEY uq_pb_design_seed_name (component_type,name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE name=VALUES(name);
START TRANSACTION;
-- Match a pre-existing manually added name only if the original source record does not already exist.
UPDATE product_builder_designs existing
JOIN pb_deploy_design_seed seed ON existing.component_type=seed.component_type AND existing.name=seed.name
LEFT JOIN product_builder_designs imported ON imported.seed_key=seed.seed_key
SET existing.seed_key=seed.seed_key
WHERE existing.seed_key IS NULL AND imported.id IS NULL;
SELECT seed.component_type,seed.name,seed.seed_key FROM pb_deploy_design_seed seed
WHERE NOT EXISTS (SELECT 1 FROM product_builder_designs existing
 WHERE existing.seed_key=seed.seed_key OR (existing.component_type=seed.component_type AND existing.name=seed.name));
COMMIT;

-- Product builder update 005: editable Graphics versions.
-- Import after update 004. Existing listing names, selections and SKUs are preserved.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS product_builder_graphics_versions (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(30) NOT NULL, sort_order INT UNSIGNED NOT NULL DEFAULT 0,
 seed_key VARCHAR(30) NULL, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_pb_graphics_version_name (name), UNIQUE KEY uq_pb_graphics_version_seed (seed_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET @pb_has_graphics_version = (SELECT COUNT(*) FROM information_schema.columns
 WHERE table_schema=DATABASE() AND table_name='product_builder_components' AND column_name='graphics_version_id');
SET @pb_graphics_version_sql = IF(@pb_has_graphics_version=0,
 'ALTER TABLE product_builder_components ADD COLUMN graphics_version_id BIGINT UNSIGNED NULL AFTER design_id', 'DO 0');
PREPARE pb_graphics_version_migration FROM @pb_graphics_version_sql;
EXECUTE pb_graphics_version_migration;
DEALLOCATE PREPARE pb_graphics_version_migration;
SET @pb_has_graphics_version_fk = (SELECT COUNT(*) FROM information_schema.table_constraints
 WHERE constraint_schema=DATABASE() AND table_name='product_builder_components' AND constraint_name='fk_pb_component_graphics_version');
SET @pb_graphics_version_sql = IF(@pb_has_graphics_version_fk=0,
 'ALTER TABLE product_builder_components ADD CONSTRAINT fk_pb_component_graphics_version FOREIGN KEY (graphics_version_id) REFERENCES product_builder_graphics_versions(id) ON DELETE RESTRICT', 'DO 0');
PREPARE pb_graphics_version_migration FROM @pb_graphics_version_sql;
EXECUTE pb_graphics_version_migration;
DEALLOCATE PREPARE pb_graphics_version_migration;
-- Default Graphics versions: stable source keys preserve names and ordering on repeat import.
CREATE TEMPORARY TABLE IF NOT EXISTS pb_deploy_graphics_version_seed (
 name VARCHAR(30) NOT NULL, sort_order INT UNSIGNED NOT NULL, seed_key VARCHAR(30) NOT NULL PRIMARY KEY
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE name=VALUES(name),sort_order=VALUES(sort_order);
START TRANSACTION;
UPDATE product_builder_graphics_versions existing
JOIN pb_deploy_graphics_version_seed seed ON existing.name=seed.name
LEFT JOIN product_builder_graphics_versions imported ON imported.seed_key=seed.seed_key
SET existing.seed_key=seed.seed_key WHERE existing.seed_key IS NULL AND imported.id IS NULL;
SELECT seed.name,seed.sort_order,seed.seed_key FROM pb_deploy_graphics_version_seed seed
WHERE NOT EXISTS (SELECT 1 FROM product_builder_graphics_versions existing WHERE existing.seed_key=seed.seed_key OR existing.name=seed.name);
COMMIT;


